package net.civeira.phylax.features.document.snippetasset.domain.gateway;

import java.util.List;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.features.document.snippet.domain.SnippetReference;

class SnippetAssetFilterUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test a entity reference contruction")
  void test_snippet_asset_filter_builder() {
    SnippetAssetFilter filter = SnippetAssetFilter.builder().build();
    Assertions.assertFalse(filter.getUid().isPresent(),
        "Uid must be empty if filter is build without it");
    filter.setUid("one");
    Assertions.assertEquals("one", filter.getUid().get(), "Uid must be the same as the assigned");
    Assertions.assertTrue(filter.getUids().isEmpty(),
        "Uid must be empty if filter is build without it");
    filter.setUids(List.of("one"));
    Assertions.assertEquals(List.of("one"), filter.getUids(),
        "Uids must be the same as the assigned");
    Assertions.assertFalse(filter.getSearch().isPresent(),
        "Search must be empty if filter is build without it");
    filter.setSearch("lookup");
    Assertions.assertEquals("lookup", filter.getSearch().get(),
        "Search must be the same as the assigned");
    Assertions.assertFalse(filter.getCode().isPresent(),
        "Code must be empty if filter is build without it");
    filter.setCode("one");
    Assertions.assertEquals("one", filter.getCode().get(), "Code must be the same as the assigned");
    Assertions.assertFalse(filter.getSnippet().isPresent(),
        "Snippet must be empty if filter is build without it");
    filter.setSnippet(SnippetReference.of("$ref"));
    Assertions.assertEquals(SnippetReference.of("$ref"), filter.getSnippet().get(),
        "Snippet must be the same as the assigned");
    Assertions.assertTrue(filter.getSnippets().isEmpty(),
        "Snippets must be empty if filter is build without it");
    filter.setSnippets(List.of("one"));
    Assertions.assertEquals(List.of("one"), filter.getSnippets(),
        "Snippets must be the same as the assigned");
    Assertions.assertFalse(filter.getSnippetTenantTenantAccesible().isPresent(),
        "SnippetTenantTenantAccesible must be empty if filter is build without it");
    filter.setSnippetTenantTenantAccesible("one");
    Assertions.assertEquals("one", filter.getSnippetTenantTenantAccesible().get(),
        "SnippetTenantTenantAccesible must be the same as the assigned");
  }
}
